'use client';
import { useState } from 'react'; import Link from 'next/link'; import { useRouter } from 'next/navigation';
export default function Login(){const[email,setEmail]=useState('');const[password,setPassword]=useState('');const[error,setError]=useState('');const router=useRouter();async function submit(e){e.preventDefault();const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});const d=await r.json();if(r.ok)router.push('/');else setError(d.message||'Login failed')}return <main className="auth-page"><form className="form-container" onSubmit={submit}><h1>Welcome Back</h1>{error&&<p className="error-message">{error}</p>}<div className="input-group"><label>Email</label><input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></div><div className="input-group"><label>Password</label><input type="password" required value={password} onChange={e=>setPassword(e.target.value)}/></div><button className="button primary-button">Login</button><div className="link-container">No account? <Link href="/register">Register</Link></div></form></main>}
